import numpy as np, math
class Body:
 def __init__(self,x,y,w,h,m,static=False):
  self.p=np.array([x,y],float);self.v=np.zeros(2);self.a=0.;self.av=0.;self.w=w;self.h=h;self.inv=0 if static else 1/m;self.ii=0 if static else 12/(m*(w*w+h*h))
 def verts(self):
  c,s=math.cos(self.a),math.sin(self.a);return np.array([[-self.w/2,-self.h/2],[self.w/2,-self.h/2],[self.w/2,self.h/2],[-self.w/2,self.h/2]])@np.array([[c,s],[-s,c]])+self.p

def cross(a,b):return a[0]*b[1]-a[1]*b[0]
def clip(poly,n,d):
 out=[]
 if not len(poly):return np.array(out)
 for k,q in enumerate(poly):
  p=poly[k-1];dp=p@n-d;dq=q@n-d
  if (dp<=0)"'!=(dq<=0):out.append(p+(q-p)*dp/(dp-dq))
  if dq<=0:out.append(q)
 return np.array(out)
def contact(a,b):
 va,vb=a.verts(),b.verts();best=1e9;norm=None
 for poly in [va,vb]:
  for i in range(2):
   edge=poly[(i+1)%4]-poly[i];n=np.array([-edge[1],edge[0]]);n/=np.linalg.norm(n)
   pa,pb=va@n,vb@n;overlap=min(pa.max(),pb.max())-max(pa.min(),pb.min())
   if overlap<-.02:return None
   if overlap<best:best=overlap;norm=n
 if (b.p-a.p)@norm<0:norm=-norm
 inter=va
 for i in range(4):
  edge=vb[(i+1)%4]-vb[i];n=np.array([edge[1],-edge[0]]);inter=clip(inter,n,vb[i]@n+.025)
  if not len(inter):return None
 tang=np.array([-norm[1],norm[0]]);inds=np.argsort(inter@tang);pts=[inter[inds[0]],inter[inds[-1]]]
 if np.linalg.norm(pts[0]-pts[1])<1:pts=pts[:1]
 return norm,max(best,0),pts

def run():
 red=Body(134,20,18,40,8,True); yellow=Body(144,45,60,10,3);blue=Body(169,80.5,12,61,3.66);floor=Body(134,-50,1000,100,1,True)
 bodies=[yellow,blue];pairs=[(yellow,red),(blue,red),(yellow,floor),(blue,floor),(yellow,blue)]
 dt=.001;states=[]
 for i in range(4251):
  for a in bodies:a.v[1]-=650*dt;a.p+=a.v*dt;a.a+=a.av*dt
  contacts=[]
  for a,b in pairs:
   co=contact(a,b)
   if co:contacts.append((a,b,*co))
  for it in range(10):
   for a,b,n,pen,pts in contacts:
    for p in pts:
     ra=p-a.p;rb=p-b.p
     vel=lambda o,r:o.v+o.av*np.array([-r[1],r[0]])
     vrel=vel(b,rb)-vel(a,ra);vn=vrel@n
     den=a.inv+b.inv+cross(ra,n)**2*a.ii+cross(rb,n)**2*b.ii
     if vn<0:
      j=-(1.04 if vn<-20 and it==0 else 1)*vn/den
      impulse=j*n
      a.v-=impulse*a.inv;b.v+=impulse*b.inv;a.av-=cross(ra,impulse)*a.ii;b.av+=cross(rb,impulse)*b.ii
      tan=np.array([-n[1],n[0]]);vrel=vel(b,rb)-vel(a,ra)
      dent=a.inv+b.inv+cross(ra,tan)**2*a.ii+cross(rb,tan)**2*b.ii
      jt=np.clip(-(vrel@tan)/dent,-.55*j,.55*j);impulse=jt*tan
      a.v-=impulse*a.inv;b.v+=impulse*b.inv;a.av-=cross(ra,impulse)*a.ii;b.av+=cross(rb,impulse)*b.ii
  for a,b,n,pen,pts in contacts:
   correction=max(0,pen-.015)*.65/(a.inv+b.inv)*n
   a.p-=correction*a.inv;b.p+=correction*b.inv
  for a in bodies:
   a.v*=.99994;a.av*=.9999
  if i%250==0:
   states.append([(b.p.copy(),b.a) for b in bodies]);print(i/1000,[(np.round(b.p,1).tolist(),round(b.a*180/math.pi,1),np.round(b.v,1).tolist()) for b in bodies])
 return states
if __name__=='"'__main__':run()
